 * Parsing of the election description read from standard input.
 */

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

export class ParseError extends Error {
  constructor(lineNumber, message) {
    super(message)
    this.lineNumber = lineNumber
  }
}

function fail(lineNumber, message) {
  throw new ParseError(lineNumber, message)
}

/**
 * Parses the raw election text into a list of declared candidates (in
 * declaration order) and a list of ballots, each `{ count, names }`.
 */
export function parseElection(text) {
  const rawLines = text.split('\n')
  if (text.endsWith('\n')) rawLines.pop()

  let candidatesSeen = false
  let ballotSeen = false
  const candidateSet = new Set()
  const candidateList = []
  const ballots = []

  for (let i = 0; i < rawLines.length; i++) {
    const lineNumber = i + 1
    const trimmed = rawLines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const tokens = trimmed.split(/\s+/)
    const word = tokens[0]

    if (word === 'candidates') {
      if (candidatesSeen || ballotSeen) {
        fail(lineNumber, 'candidates must be declared once, before any ballot')
      }
      const names = tokens.slice(1)
      if (names.length === 0) {
        fail(lineNumber, 'expected candidates <name>...')
      }
      for (const name of names) {
        if (!NAME_RE.test(name)) {
          fail(lineNumber, `invalid candidate name ${name}`)
        }
        if (candidateSet.has(name)) {
          fail(lineNumber, `candidate ${name} is declared twice`)
        }
        candidateSet.add(name)
        candidateList.push(name)
      }
      candidatesSeen = true
    } else if (word === 'ballot') {
      if (!candidatesSeen) {
        fail(lineNumber, 'candidates must be declared once, before any ballot')
      }
      if (tokens.length < 3) {
        fail(lineNumber, 'expected ballot <count> <candidate>...')
      }
      const countStr = tokens[1]
      if (!COUNT_RE.test(countStr)) {
        fail(lineNumber, 'count must be a positive integer')
      }
      const count = Number(countStr)
      const names = tokens.slice(2)
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          fail(lineNumber, `unknown candidate ${name}`)
        }
        if (seen.has(name)) {
          fail(lineNumber, `candidate ${name} is repeated`)
        }
        seen.add(name)
      }
      ballots.push({ count, names })
      ballotSeen = true
    } else {
      fail(lineNumber, `unknown directive ${word}`)
    }
  }

  if (!candidatesSeen) {
    fail(null, 'no candidates')
  }

  return { candidates: candidateList, ballots }
}
"}

