{"file_path":"src/election.js","content":"/**
 * Instant-runoff counting.
 */

/**
 * Breaks a tie among candidates who are level for elimination, by comparing
 * their vote counts across the rounds already tallied (this one included),
 * starting from the first round, and falling back to reverse name order.
 */
function breakTie(tied, history, currentRound) {
  let candidates = tied
  while (candidates.length > 1) {
    let separated = false
    for (let round = 1; round <= currentRound; round++) {
      const counts = candidates.map((c) => history[round][c])
      const min = Math.min(...counts)
      if (!counts.every((v) => v === min)) {
        candidates = candidates.filter((c) => history[round][c] === min)
        separated = true
        break
      }
    }
    if (!separated) break
  }
  if (candidates.length === 1) return candidates[0]
  return candidates.reduce((a, b) => (a > b ? a : b))
}

/**
 * Runs the full election and returns `{ rounds, winner }`, where `rounds` is
 * an array of `{ counts, exhausted, eliminated }` (`counts` maps continuing
 * candidate names to their vote count that round, `eliminated` is the name
 * eliminated after the round or `null` on the terminal round) and `winner` is
 * the winning candidate's name or `null`.
 */
export function runElection({ candidates, ballots }) {
  const continuing = new Set(candidates)
  const history = {}
  const rounds = []
  let winner = null
  let roundNumber = 0

  for (;;) {
    roundNumber++
    const counts = {}
    for (const c of continuing) counts[c] = 0
    let exhausted = 0

    for (const ballot of ballots) {
      const target = ballot.names.find((n) => continuing.has(n))
      if (target !== undefined) {
        counts[target] += ballot.count
      } else {
        exhausted += ballot.count
      }
    }

    history[roundNumber] = counts
    const activeTotal = Object.values(counts).reduce((a, b) => a + b, 0)

    if (activeTotal === 0) {
      rounds.push({ counts, exhausted, eliminated: null })
      break
    }

    let roundWinner = null
    for (const c of continuing) {
      if (counts[c] * 2 > activeTotal) {
        roundWinner = c
        break
      }
    }

    if (roundWinner !== null) {
      winner = roundWinner
      rounds.push({ counts, exhausted, eliminated: null })
      break
    }

    const contArr = [...continuing]
    const minVal = Math.min(...contArr.map((c) => counts[c]))
    const tied = contArr.filter((c) => counts[c] === minVal)
    const eliminated = breakTie(tied, history, roundNumber)
    continuing.delete(eliminated)
    rounds.push({ counts, exhausted, eliminated })
  }

  return { rounds, winner }
}
"}

