/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { readFileSync } from 'node:fs'
import { parseElection, ParseError } from './parse.js'
import { runElection } from './election.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (mode !== 'rounds' && mode !== 'tally') {
    fail('usage: cli.js rounds|tally')
  }

  const input = readFileSync(0, 'utf8')

  let election
  try {
    election = parseElection(input)
  } catch (err) {
    if (err instanceof ParseError) {
      if (err.lineNumber === null) {
        fail(err.message)
      } else {
        fail(`line ${err.lineNumber}: ${err.message}`)
      }
    }
    throw err
  }

  const { rounds, winner } = runElection(election)

  const out = []
  if (mode === 'rounds') {
    rounds.forEach((round, index) => {
      const names = Object.keys(round.counts)
      names.sort((a, b) => {
        if (round.counts[b] !== round.counts[a]) return round.counts[b] - round.counts[a]
        return a < b ? -1 : a > b ? 1 : 0
      })
      const parts = names.map((n) => `${n}=${round.counts[n]}`)
      parts.push(`exhausted=${round.exhausted}`)
      out.push(`round ${index + 1}: ${parts.join(' ')}`)
      if (round.eliminated !== null) {
        out.push(`eliminated ${round.eliminated}`)
      }
    })
  } else {
    out.push(`rounds ${rounds.length}`)
  }

  out.push(winner !== null ? `winner ${winner}` : 'no winner')

  process.stdout.write(out.join('\n') + '\n')
}

main()
"}

